import { useEffect, useRef, useState } from 'react';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { PageHeader } from '@kerfjs/ui/page-header';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { ResizableRegion, wireResizableRegions } from '@kerfjs/ui/resizable-region';
import '@kerfjs/ui/layout.css';
import './shell.css';

export function ApplicationShell() {
  const root = useRef<HTMLDivElement>(null);
  const [section, setSection] = useState('Projects');
  const [inspector, setInspector] = useState(true);
  const [width, setWidth] = useState(() => {
    if (typeof window === 'undefined') return 320;
    try { const n = Number(localStorage.getItem('inspector-width')); return n >= 240 && n <= 480 ? n : 320; }
    catch { return 320; }
  });
  useEffect(() => {
    if (!root.current) return;
    const dispose = wireResizableRegions(root.current);
    return () => dispose();
  }, []);
  useEffect(() => { try { localStorage.setItem('inspector-width', String(width)); } catch {} }, [width]);
  return <div ref={root} className="kui-layout app-shell" style={{ '--inspector-width': width + 'px' } as React.CSSProperties}>
    <a href="#workspace" className="skip-link">Skip to workspace</a>
    <Toolbar><strong>Studio</strong><button type="button" aria-controls="inspector" aria-expanded={inspector} onClick={() => setInspector(!inspector)}>Inspector</button></Toolbar>
    <div className="app-panes">
      <nav aria-label="Workspace navigation" className="kui-sidebar app-nav" tabIndex={0}>
        <section className="kui-sidebar-section"><MenuHeader>Workspace</MenuHeader>
          {['Projects', 'Activity'].map(label => <MenuItem key={label} aria-current={section === label ? 'page' : undefined} onClick={() => setSection(label)}>{label}</MenuItem>)}
        </section>
        <section className="kui-sidebar-section"><MenuHeader>Organization</MenuHeader><MenuItem onClick={() => setSection('People')}>People</MenuItem></section>
      </nav>
      <main id="workspace" tabIndex={-1} className="app-workspace">
        <PageHeader>{section}</PageHeader>
        <div className="app-scroll" tabIndex={0} aria-label={section + ' content'}><p>Your {section.toLowerCase()} workspace.</p></div>
      </main>
      {inspector && <aside id="inspector" className="app-inspector" aria-label="Inspector">
        <ResizableRegion>
          <label className="inspector-size">Inspector width
            <input type="range" min={240} max={480} step={16} value={width} onChange={e => setWidth(Number(e.target.value))} />
          </label>
          <div className="app-scroll" tabIndex={0} aria-label="Inspector details"><h2>Details</h2><p>Select an item to inspect it.</p></div>
        </ResizableRegion>
      </aside>}
    </div>
  </div>;
}

