html, body, #root { height: 100%; margin: 0; }
.app-shell { height: 100dvh; display: grid; grid-template-rows: auto minmax(0, 1fr); overflow: hidden; }
.app-panes { display: flex; min-height: 0; min-width: 0; }
.app-nav { flex: 0 0 15rem; overflow: auto; }
.app-workspace { flex: 1; min-width: 0; min-height: 0; display: flex; flex-direction: column; }
.app-scroll { flex: 1; min-height: 0; overflow: auto; padding: var(--kui-space-4, 1rem); overflow-wrap: anywhere; }
.app-inspector { flex: 0 0 var(--inspector-width); min-width: 0; min-height: 0; display: flex; flex-direction: column; overflow: auto; }
.app-inspector .app-scroll { overflow: visible; }
.inspector-size { display: flex; flex-wrap: wrap; align-items: center; padding: var(--kui-space-4, 1rem); }
:focus-visible { outline: 2px solid currentColor; outline-offset: 3px; }
.skip-link { position: absolute; inset-block-start: 0; transform: translateY(-120%); }
.skip-link:focus { transform: none; z-index: 10; background: Canvas; color: CanvasText; }
@media (max-width: 48rem) {
 .app-panes { display: grid; grid-template-rows: auto minmax(10rem, 1fr) auto; overflow: auto; }
 .app-nav { display: flex; flex-wrap: wrap; max-height: 9rem; }
 .app-workspace { min-height: 18rem; }
 .app-inspector { max-height: 15rem; width: auto; }
 .inspector-size { display: none; }
}
